    ('IGUI_LW_InspectInverter', '%1: Zustand %2, %3|%1: estado %2, %3|%1: estado %2, %3|%1: condição %2, %3|%1: состояние %2, %3|%1: 状况 %2, %3|%1: 状態%2、%3|%1: 상태 %2, %3|%1: durum %2, %3'),
